int climb_stairs(int n) {
    if (n < 0) return 0;
    if (n <= 1) return 1;
    int prev2 = 1, prev1 = 1;
    for (int i = 2; i <= n; ++i) {
        int cur = prev1 + prev2;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int house_robber(const int *nums, int n) {
    if (n <= 0) return 0;
    int prev2 = 0, prev1 = 0;
    for (int i = 0; i < n; ++i) {
        int cur = prev1 > prev2 + nums[i] ? prev1 : prev2 + nums[i];
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

int coin_change_min(const int *coins, int nc, int amount) {
    if (amount < 0) return -1;
    const int INF = INT_MAX - 1;
    int *dp = malloc((size_t)(amount + 1) * sizeof *dp);
    if (!dp) return -1;
    dp[0] = 0;
    for (int a = 1; a <= amount; ++a) {
        dp[a] = INF;
        for (int c = 0; c < nc; ++c)
            if (coins[c] > 0 && a - coins[c] >= 0 && dp[a - coins[c]] + 1 < dp[a])
                dp[a] = dp[a - coins[c]] + 1;
    }
    int ans = (dp[amount] >= INF) ? -1 : dp[amount];
    free(dp);
    return ans;
}

int longest_increasing_subsequence(const int *nums, int n) {
    if (n <= 0) return 0;
    int *dp = malloc((size_t)n * sizeof *dp);
    if (!dp) return 0;
    int best = 1;
    for (int i = 0; i < n; ++i) {
        dp[i] = 1;
        for (int j = 0; j < i; ++j)
            if (nums[j] < nums[i] && dp[j] + 1 > dp[i])
                dp[i] = dp[j] + 1;
        if (dp[i] > best) best = dp[i];
    }
    free(dp);
    return best;
}

int knapsack_01(const int *w, const int *v, int n, int cap) {
    if (cap <= 0 || n <= 0) return 0;
    int *dp = calloc((size_t)(cap + 1), sizeof *dp);
    if (!dp) return 0;
    for (int i = 0; i < n; ++i)
        for (int c = cap; c >= w[i]; --c) {
            int cand = dp[c - w[i]] + v[i];
            if (cand > dp[c]) dp[c] = cand;
        }
    int ans = dp[cap];
    free(dp);
    return ans;
}

int edit_distance(const char *a, const char *b) {
    int la = (int)strlen(a), lb = (int)strlen(b);
    int W = lb + 1;
    int *dp = malloc((size_t)(la + 1) * (size_t)W * sizeof *dp);
    if (!dp) return -1;
    for (int i = 0; i <= la; ++i) dp[i * W + 0] = i;
    for (int j = 0; j <= lb; ++j) dp[0 * W + j] = j;
    for (int i = 1; i <= la; ++i)
        for (int j = 1; j <= lb; ++j) {
            if (a[i-1] == b[j-1]) {
                dp[i*W+j] = dp[(i-1)*W+(j-1)];
            } else {
                int del = dp[(i-1)*W+j], ins = dp[i*W+(j-1)], sub = dp[(i-1)*W+(j-1)];
                int m = del < ins ? del : ins; if (sub < m) m = sub;
                dp[i*W+j] = 1 + m;
            }
        }
    int ans = dp[la*W+lb];
    free(dp);
    return ans;
}

int longest_common_subsequence(const char *a, const char *b) {
    int la = (int)strlen(a), lb = (int)strlen(b);
    int W = lb + 1;
    int *dp = calloc((size_t)(la + 1) * (size_t)W, sizeof *dp);
    if (!dp) return 0;
    for (int i = 1; i <= la; ++i)
        for (int j = 1; j <= lb; ++j) {
            if (a[i-1] == b[j-1])
                dp[i*W+j] = dp[(i-1)*W+(j-1)] + 1;
            else {
                int u = dp[(i-1)*W+j], l = dp[i*W+(j-1)];
                dp[i*W+j] = u > l ? u : l;
            }
        }
    int ans = dp[la*W+lb];
    free(dp);
    return ans;
}

int unique_paths(int m, int n) {
    if (m <= 0 || n <= 0) return 0;
    int *row = malloc((size_t)n * sizeof *row);
    if (!row) return 0;
    for (int j = 0; j < n; ++j) row[j] = 1;
    for (int i = 1; i < m; ++i)
        for (int j = 1; j < n; ++j)
            row[j] = row[j] + row[j - 1];
    int ans = row[n - 1];
    free(row);
    return ans;
}

int max_product_subarray(const int *nums, int n) {
    if (n <= 0) return 0;
    int maxp = nums[0], minp = nums[0], ans = nums[0];
    for (int i = 1; i < n; ++i) {
        int x = nums[i], a = maxp * x, b = minp * x;
        int nmax = x; if (a > nmax) nmax = a; if (b > nmax) nmax = b;
        int nmin = x; if (a < nmin) nmin = a; if (b < nmin) nmin = b;
        maxp = nmax; minp = nmin;
        if (maxp > ans) ans = maxp;
    }
    return ans;
}
